trait Component { def update(dt: Double): Unit }

class Actor(parts: List[Component]) {
  def update(dt: Double): Unit = parts.foreach(_.update(dt))
}

// Cake-style static wiring: self-types declare the dependency
trait PhysicsComponent { def physics: Physics }
trait RenderComponent { this: PhysicsComponent => def graphics: Graphics }
object Registry extends PhysicsComponent with RenderComponent {
  val physics = new Box2DPhysics
  val graphics = new SpriteGraphics
}
